application.css:
:root {
  color-scheme: light;
  --ink: #172033;
  --muted: #526078;
  --surface: #ffffff;
  --page: #eef3f8;
  --border: #b7c3d4;
  --accent: #174ea6;
  --accent-light: #e8f0ff;
  --error: #a12626;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  color: var(--ink);
  background: var(--page);
  line-height: 1.5;
}

.page-shell {
  width: min(100% - 2rem, 52rem);
  margin: 0 auto;
  padding: 2rem 0 3rem;
}

.quiz-header { margin-bottom: 1.5rem; }
.eyebrow {
  margin: 0 0 .25rem;
  color: var(--accent);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .08em;
  font-size: .8rem;
}

h1, h2 { line-height: 1.2; }
h1 { margin: 0 0 .5rem; font-size: clamp(2rem, 6vw, 3rem); }
h2 { margin: 0 0 1rem; font-size: 1.35rem; }
.quiz-header p:last-child { color: var(--muted); margin: 0; }

.question-list, .result {
  background: var(--surface);
  border-radius: .75rem;
  padding: clamp(1rem, 4vw, 1.5rem);
  box-shadow: 0 .2rem .8rem rgba(23, 32, 51, .08);
}

.question-card {
  border: 0;
  border-top: 1px solid var(--border);
  margin: 0;
  padding: 1.25rem 0;
}
.question-card:first-of-type { border-top: 0; padding-top: .25rem; }
legend { font-weight: 700; padding: 0; width: 100%; }
.options { display: grid; gap: .65rem; margin-top: .9rem; }
.option {
  display: flex;
  align-items: center;
  gap: .7rem;
  border: 1px solid var(--border);
  border-radius: .5rem;
  padding: .7rem .8rem;
  cursor: pointer;
}
.option:hover, .option:has(input:checked) { border-color: var(--accent); background: var(--accent-light); }
.option input { width: 1.1rem; height: 1.1rem; accent-color: var(--accent); }
.option:focus-within { outline: 3px solid #7da9ed; outline-offset: 2px; }

.submit-button {
  border: 0;
  border-radius: .5rem;
  background: var(--accent);
  color: white;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  margin: 1.25rem 0;
  padding: .8rem 1.2rem;
}
.submit-button:hover { background: #103d83; }
.submit-button:focus-visible { outline: 3px solid #f2b544; outline-offset: 3px; }
.form-message { color: var(--error); font-weight: 700; margin: 1rem 0 0; }
.result { margin-top: 1rem; }
.result h2 { margin-bottom: .4rem; }
.score { font-size: 1.5rem; font-weight: 800; margin: 0; }
#result-message { color: var(--muted); margin: .2rem 0 0; }

@media (max-width:  thirtyrem) {
  .page-shell { width: min(100% - 1rem, 52rem); padding-top: 1rem; }
}

