const form = document.querySelector('#quiz-form');
const message = document.querySelector('#form-message');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const resultMessage = document.querySelector('#result-message');

const correctAnswers = Object.freeze({
  'question-1': 'css',
  'question-2': 'h1',
  'question-3': 'const'
});

function getSelectedAnswer(questionName) {
  const selected = form.querySelector(`input[name="${questionName}"]:checked`);
  return selected ? selected.value : null;
}

function showValidationError(missingQuestions) {
  const questionText = missingQuestions.length === 1
    ? 'question'
    : 'questions';
  message.textContent = `Please answer ${questionText} ${missingQuestions.join(', ')} before submitting.`;
  message.hidden = false;
}

function clearValidationError() {
  message.textContent = '';
  message.hidden = true;
}

function calculateScore() {
  return Object.entries(correctAnswers).reduce((score, [questionName, answer]) => {
    return score + (getSelectedAnswer(questionName) === answer ? 1 : 0);
  }, 0);
}

function displayScore(score) {
  scoreElement.textContent = `${score} out of 3`;
  scoreElement.dataset.score = String(score);
  resultMessage.textContent = score === 3
    ? 'Excellent work — every answer is correct.'
    : 'Review the questions and try again if you would like to improve your score.';
}

function handleSubmit(event) {
  event.preventDefault();
  const missingQuestions = Object.keys(correctAnswers)
    .map((questionName, index) => getSelectedAnswer(questionName) ? null : index + 1)
    .filter(Boolean);

  if (missingQuestions.length > 0) {
    showValidationError(missingQuestions);
    return;
  }

  clearValidationError();
  displayScore(calculateScore());
}

form.addEventListener('submit', handleSubmit);
